"""Application errors rendered as stable JSON error responses."""

from __future__ import annotations


class APIError(Exception):
    def __init__(self, status_code: int, code: str, message: str) -> None:
        self.status_code = status_code
        self.code = code
        self.message = message
        super().__init__(message)


class NotFoundError(APIError):
    """A referenced dataset, schema version or field does not exist (404)."""

    def __init__(self, message: str) -> None:
        super().__init__(404, "not_found", message)


class ConflictError(APIError):
    """The request conflicts with already stored state (409)."""

    def __init__(self, message: str) -> None:
        super().__init__(409, "conflict", message)


class RequestInvalidError(APIError):
    """The request is structurally or semantically invalid (422)."""

    def __init__(self, message: str) -> None:
        super().__init__(422, "validation_error", message)

def _require_schema_version(
    conn: sqlite3.Connection, dataset: dict, version_number: int
) -> sqlite3.Row:
    version_row = conn.execute(
        "SELECT id, version, created_at FROM schema_versions "
        "WHERE dataset_id = ? AND version = ?",
        (dataset["id"], version_number),
    ).fetchone()
    if version_row is None:
        raise NotFoundError(
            f"Schema version {version_number} of dataset '{dataset['name']}' does not exist"
        )
    return version_row


def _version_field_names(conn: sqlite3.Connection, version_id: int) -> set[str]:
    rows = conn.execute(
        "SELECT name FROM schema_fields WHERE version_id = ?", (version_id,)
    ).fetchall()
    return {row["name"] for row in rows}


def _is_finite_number(value: Any) -> bool:
    # bool is a subclass of int; a boolean is not a numeric value here.
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return False
    return math.isfinite(value)


